 const [page,setPage]=useState('Explore'); const [tripFilter,setTripFilter]=useState('Upcoming'); const [tripsLoading,setTripsLoading]=useState(false); const [tripsError,setTripsError]=useState(''); const [tripActionBusy,setTripActionBusy]=useState(false); const [tripDetailLoading,setTripDetailLoading]=useState(false); const [tripActionError,setTripActionError]=useState(''); const [selectedBooking,setSelectedBooking]=useState(null); const [screen,setScreen]=useState(''); const [selected,setSelected]=useState(null); const [category,setCategory]=useState('All'); const [search,setSearch]=useState(''); const [sort,setSort]=useState('Recommended'); const [filterOpen,setFilterOpen]=useState(false); const [minPrice,setMinPrice]=useState(''); const [maxPrice,setMaxPrice]=useState(''); const [transmissionFilter,setTransmissionFilter]=useState('Any'); const [fuelFilter,setFuelFilter]=useState('Any'); const [seatsFilter,setSeatsFilter]=useState('Any'); const [draftCategory,setDraftCategory]=useState('All'); const [draftSort,setDraftSort]=useState('Recommended'); const [draftMinPrice,setDraftMinPrice]=useState(''); const [draftMaxPrice,setDraftMaxPrice]=useState(''); const [draftTransmission,setDraftTransmission]=useState('Any'); const [draftFuel,setDraftFuel]=useState('Any'); const [draftSeats,setDraftSeats]=useState('Any'); const [filterError,setFilterError]=useState(''); const [delivery,setDelivery]=useState(true); const [address,setAddress]=useState(''); const [date,setDate]=useState(''); const [days,setDays]=useState('1'); const [name,setName]=useState(''); const [phone,setPhone]=useState(''); const [email,setEmail]=useState(''); const [promo,setPromo]=useState(''); const [applied,setApplied]=useState(false); const [trips,setTrips]=useState([]); const [authToken,setAuthToken]=useState(authenticatedUser?.token || null); const [authError,setAuthError]=useState(''); const [profileTab,setProfileTab]=useState('Personal details'); const [toast,setToast]=useState(''); const [bookingBusy,setBookingBusy]=useState(false); const [bookingError,setBookingError]=useState(''); const [quote,setQuote]=useState(null); const [pickupTime,setPickupTime]=useState('10:00'); const [returnDate,setReturnDate]=useState(''); const [returnTime,setReturnTime]=useState('10:00'); const [paymentMethod,setPaymentMethod]=useState('upi'); const [paymentBusy,setPaymentBusy]=useState(false); const [paymentError,setPaymentError]=useState(''); const [paymentState,setPaymentState]=useState(null); const [paymentReferenceDraft,setPaymentReferenceDraft]=useState('');
 const [availability,setAvailability]=useState(null); const [locationOpen,setLocationOpen]=useState(false); const [selectedAddressId,setSelectedAddressId]=useState(null); const [vehicles,setVehicles]=useState([]); const [vehicleCatalog,setVehicleCatalog]=useState([]); const [vehiclesSource,setVehiclesSource]=useState('loading'); const [vehiclesLoading,setVehiclesLoading]=useState(false); const [vehiclesError,setVehiclesError]=useState(''); const [selectedCity,setSelectedCity]=useState('Jaipur'); const [explorePickupDate,setExplorePickupDate]=useState(''); const [exploreReturnDate,setExploreReturnDate]=useState(''); const searchDebounceRef=useRef(null); const vehicleRequestIdRef=useRef(0);
 const bookingWindow=useMemo(()=>{if(!date||!returnDate||!pickupTime||!returnTime)return null;if(!isValidDateTimeInput(date,pickupTime)||!isValidDateTimeInput(returnDate,returnTime))return null;const start=new Date(`${date}T${pickupTime}:00`);const end=new Date(`${returnDate}T${returnTime}:00`);if(Number.isNaN(start.getTime())||Number.isNaN(end.getTime()))return null;return {startAt:start.toISOString(),endAt:end.toISOString(),startMs:start.getTime(),endMs:end.getTime(),days:Math.max(1,Math.ceil((end.getTime()-start.getTime())/86400000))};},[date,returnDate,pickupTime,returnTime]); const duration=bookingWindow?.days||1; const subtotal=quote?.rental ?? (selected?selected.price*duration:0); const deliveryFee=quote?.deliveryFee ?? 0; const platformFee=quote?.platformFee ?? 0; const securityDeposit=quote?.securityDeposit ?? 0; const total=quote?.total ?? (subtotal+deliveryFee+platformFee+securityDeposit);
 const filterSource=vehicleCatalog.length?vehicleCatalog:vehicles;
 const categoryOptions=useMemo(()=>['All',...uniqueSorted(filterSource.map(v=>v.type))],[filterSource]);
 const transmissionOptions=useMemo(()=>['Any',...uniqueSorted(filterSource.map(v=>v.transmission))],[filterSource]);
 const fuelOptions=useMemo(()=>['Any',...uniqueSorted(filterSource.map(v=>v.fuel))],[filterSource]);
 const seatsOptions=useMemo(()=>['Any',...uniqueSorted(filterSource.map(v=>v.seats?String(v.seats):null))],[filterSource]);
 const activeFilterCount=useMemo(()=>[minPrice,maxPrice,transmissionFilter,fuelFilter,seatsFilter].filter(value=>value&&value!=='Any').length,[minPrice,maxPrice,transmissionFilter,fuelFilter,seatsFilter]);
 const filtered=useMemo(()=>{const query=search.trim().toLowerCase();const min=minPrice.trim()===''?null:Number(minPrice);const max=maxPrice.trim()===''?null:Number(maxPrice);return [...vehicles].filter(v=>{const text=[v.name,v.detail,v.id].filter(Boolean).join(' ').toLowerCase();return (category==='All'||v.type===category)&&(!query||text.includes(query))&&(min===null||Number.isFinite(min)&&v.price>=min)&&(max===null||Number.isFinite(max)&&v.price<=max)&&(transmissionFilter==='Any'||String(v.transmission||'').toLowerCase()===transmissionFilter.toLowerCase())&&(fuelFilter==='Any'||String(v.fuel||'').toLowerCase()===fuelFilter.toLowerCase())&&(seatsFilter==='Any'||String(v.seats||'')===seatsFilter);}).sort((a,b)=>sort==='Price: low to high'?a.price-b.price:sort==='Price: high to low'?b.price-a.price:sort==='Name: A to Z'?a.name.localeCompare(b.name):0);},[vehicles,category,search,minPrice,maxPrice,transmissionFilter,fuelFilter,seatsFilter,sort]);
 const lowestPrice=useMemo(()=>filtered.length?Math.min(...filtered.map(v=>v.price)):null,[filtered]);
 const exploreDateError=useMemo(()=>{if(!explorePickupDate&&!exploreReturnDate)return '';if(!explorePickupDate||!exploreReturnDate)return 'Add both pickup and return dates to carry them into checkout.';if(!isValidDateTimeInput(explorePickupDate,'10:00')||!isValidDateTimeInput(exploreReturnDate,'10:00'))return 'Use valid dates in YYYY-MM-DD format.';const start=new Date(`${explorePickupDate}T10:00:00`);const end=new Date(`${exploreReturnDate}T10:00:00`);return end<=start?'Return date must be after pickup date.':'';},[explorePickupDate,exploreReturnDate]);
 const openBooking=v=>{if(!authToken){setAuthError('Sign in to book a ride.');setScreen('auth');return;}if(!v?.id){setToast('This ride cannot be booked right now.');return;}setSelected(v);setDate(explorePickupDate||'');setPickupTime('10:00');setReturnDate(exploreReturnDate||'');setReturnTime('10:00');setDays('1');setDelivery(true);setAddress('');setQuote(null);setBookingError('');setPaymentMethod('upi');setScreen('booking');}
 const cityOptions=useMemo(()=>uniqueSorted((vehicleCatalog.length?vehicleCatalog:vehicles).map(v=>v.city).filter(Boolean)),[vehicleCatalog,vehicles]);
 const selectSavedAddress=a=>{setSelectedAddressId(a.id);setAddress([a.street,a.area,a.city].filter(Boolean).join(', ')+(a.postalCode?` — ${a.postalCode}`:''));};
 const handleSaveAddress=next=>{setAddresses(xs=>{const existing=editingAddress?.id;if(existing)return xs.map(x=>x.id===existing?{...next,id:existing,default:x.default}:x);return [...xs,{...next,id:String(Date.now()),default:xs.length===0}];});setEditingAddress(null);setScreen('addresses');setToast('Address saved locally.');};
 const loadVehicles=async()=>{const requestId=++vehicleRequestIdRef.current;setVehiclesLoading(true);setVehiclesError('');try{const type=category==='All'?'':category.toLowerCase();const query=search.trim();const result=await rideOnApi.listVehicles({city:selectedCity,type,q:query});const next=normalizeVehicleList(result);if(requestId!==vehicleRequestIdRef.current)return;if(!query&&!type)setVehicleCatalog(next);setVehicles(next);setVehiclesSource('live');}catch(error){if(requestId!==vehicleRequestIdRef.current)return;setVehicles([]);setVehicleCatalog([]);setVehiclesSource('unavailable');setVehiclesError(error.message||'Live vehicle inventory is unavailable.');}finally{if(requestId===vehicleRequestIdRef.current)setVehiclesLoading(false);}};
 useEffect(()=>{if(searchDebounceRef.current)clearTimeout(searchDebounceRef.current);searchDebounceRef.current=setTimeout(()=>loadVehicles(),350);return()=>{if(searchDebounceRef.current)clearTimeout(searchDebounceRef.current);};},[search,category,selectedCity]);
