 const openFilterSheet=()=>{setDraftCategory(category);setDraftSort(sort);setDraftMinPrice(minPrice);setDraftMaxPrice(maxPrice);setDraftTransmission(transmissionFilter);setDraftFuel(fuelFilter);setDraftSeats(seatsFilter);setFilterError('');setFilterOpen(true);};
 const applyFilters=()=>{const min=draftMinPrice.trim();const max=draftMaxPrice.trim();if(min&&!/^\d+(\.\d+)?$/.test(min))return setFilterError('Minimum price must be a valid number.');if(max&&!/^\d+(\.\d+)?$/.test(max))return setFilterError('Maximum price must be a valid number.');if(min&&max&&Number(min)>Number(max))return setFilterError('Minimum price cannot be greater than maximum price.');setCategory(draftCategory);setSort(draftSort);setMinPrice(min);setMaxPrice(max);setTransmissionFilter(draftTransmission);setFuelFilter(draftFuel);setSeatsFilter(draftSeats);setFilterError('');setFilterOpen(false);};
 const resetFilters=()=>{setCategory('All');setDraftCategory('All');setSort('Recommended');setDraftSort('Recommended');setMinPrice('');setMaxPrice('');setDraftMinPrice('');setDraftMaxPrice('');setTransmissionFilter('Any');setDraftTransmission('Any');setFuelFilter('Any');setDraftFuel('Any');setSeatsFilter('Any');setDraftSeats('Any');setFilterError('');setFilterOpen(false);};
 const categoryLabel=type=>type==='All'?'All rides':type;
 const waitForPaymentConfirmation=async(bookingId)=>{
   const delays=[900,1200,1600,2200,3000,4000,5000];
   for(const delay of delays){
     await new Promise(resolve=>setTimeout(resolve,delay));
     const result=await rideOnApi.getBooking(bookingId);
     const booking=result?.booking||result?.data;
     const status=String(booking?.paymentStatus||'').toLowerCase();
     const trip=normalizeTrip(booking);
     setTrips(current=>current.some(t=>String(t.id)===String(trip.id))?current.map(t=>String(t.id)===String(trip.id)?{...t,...trip}:t):[trip,...current]);
     setSelectedBooking(trip);
     if(status==='paid'||status==='failed'||status==='refunded') return {booking:trip,status};
   }
   return {booking:null,status:'pending'};
 };
 const finishBooking=async()=>{
   if(bookingBusy||paymentBusy)return;
   setBookingError('');setPaymentError('');
   if(!selected)return setBookingError('Choose a vehicle before continuing.');
   const mobile=phone.replace(/\D/g,'');
   if(name.trim().length<2)return setBookingError('Enter your full name.');
   if(mobile.length<10)return setBookingError('Enter a valid mobile number.');
   if(!bookingWindow)return setBookingError('Complete valid pickup and return date/time.');
   if(bookingWindow.endMs<=bookingWindow.startMs)return setBookingError('Return must be after pickup.');
   if(bookingWindow.startMs<Date.now())return setBookingError('Pickup cannot be in the past.');
   if(delivery&&!address.trim())return setBookingError('Add a delivery address or turn off doorstep delivery.');
   if(!quote?.total||Number(quote.total)<=0)return setBookingError('Refresh the server quote before payment.');
   setBookingBusy(true);
   try{
     const availabilityResult=await rideOnApi.availability(selected.id,{startAt:bookingWindow.startAt,endAt:bookingWindow.endAt});
     setAvailability(availabilityResult);
     if(!availabilityResult?.available)throw Object.assign(new Error('This vehicle is unavailable for the selected dates.'),{code:'VEHICLE_UNAVAILABLE'});
     const idempotencyKey=`rideon:${selected.id}:${bookingWindow.startAt}:${bookingWindow.endAt}:${mobile}`;
     const result=await rideOnApi.createBooking({vehicleId:selected.id,customerName:name.trim(),phone:mobile,startAt:bookingWindow.startAt,endAt:bookingWindow.endAt,delivery,address:delivery?address.trim():'Self pickup'},idempotencyKey);
     const booking=result?.booking||result?.data;
     if(!booking?.bookingId)throw new Error('Booking request was not acknowledged by the server.');
     const trip=normalizeTrip(booking);
     setTrips(old=>old.some(t=>String(t.id)===String(trip.id))?old:[trip,...old]);
     setSelectedBooking(trip);
     setQuote(booking.pricing||quote);
     setPaymentState(null);
     setScreen('payment');
   }catch(error){
     if(error?.code==='VEHICLE_UNAVAILABLE')setBookingError('This vehicle was just booked for part of those dates. Choose another date or vehicle.');
     else setBookingError(error.message||'Could not create the booking request. Check your connection and try again.');
   }finally{setBookingBusy(false);}
 };
 const startPayment=async()=>{
   if(paymentBusy||!selectedBooking?.id)return;
   setPaymentBusy(true);setPaymentError('');
   try{
     const orderResult=await rideOnApi.createPaymentOrder({bookingId:selectedBooking.id,idempotencyKey:`payment:${selectedBooking.id}`});
     const payment=orderResult?.payment;
     if(!payment?.id||!payment?.amount)throw new Error('UPI payment request was not created by the server.');
     setPaymentState('pending');
     setPaymentError('');
     const upiUri=payment.upiUri;
     if(upiUri) {
       try {
         const Linking = require('react-native').Linking;
         const canOpen=await Linking.canOpenURL(upiUri);
         if(canOpen) await Linking.openURL(upiUri);
       } catch {}
     }
     setPaymentError('Complete the UPI payment in your UPI app. Return to RideOn and submit the transaction reference to begin verification.');
   }catch(error){
     if(error?.code==='PAYMENT_NOT_CONFIGURED')setPaymentError('UPI payments are not configured on the RideOn server yet.');
     else setPaymentError(error.message||'Could not start the UPI payment. Your booking remains safe.');
     setPaymentState('failed');
   }finally{setPaymentBusy(false);}
 };
 const submitPaymentReference=async(reference)=>{
   if(paymentBusy||!selectedBooking?.id||!paymentState)return;
   const value=String(reference||'').trim();
   if(value.length<4)return setPaymentError('Enter the UPI transaction reference/UTR.');
   setPaymentBusy(true);setPaymentError('');
   try{
     const payment=await rideOnApi.getPaymentByBooking?await rideOnApi.getPaymentByBooking(selectedBooking.id):null;
     const paymentId=payment?.payment?.id||payment?.id;
     if(!paymentId)throw new Error('No active UPI payment was found for this booking.');
     const result=await rideOnApi.verifyPayment(paymentId,{bookingId:selectedBooking.id,transactionReference:value});
     setPaymentState(result?.verification==='pending_verification'?'pending_verification':'pending');
     setPaymentError('Payment submitted. RideOn will mark it paid only after authoritative UPI verification. Do not make another payment.');
   }catch(error){
     setPaymentError(error.message||'Could not submit the transaction reference.');
   }finally{setPaymentBusy(false);}
 };
